// State management
const items = ref<CommentResource[]>([]);
const page = ref(0); // Start at 0, first load will be page 1
const hasMore = ref(true);
const error = ref<Error | null>(null);

const pageSize = 15;

// Identifier changes when modal opens with valid auth - triggers InfiniteLoading reset
const identifier = computed(() => {
  return `idea-comments-${props.ideaId}-${props.visible && isAuthenticated.value}`;
});

// Handle load event from InfiniteList
const handleLoad = async (state: StateHandler) => {
  // Don't load if modal isn't visible or not authenticated
  if (!props.visible || !isAuthenticated.value) {
    state.complete();
    return;
  }

  const nextPage = page.value + 1;
  error.value = null;

  try {
    const params: QueryParams = {
      page: nextPage,
      per_page: pageSize,
      orders: [order('created_at', 'desc')],
    };

    const response: PaginatedResponse<CommentResource> = await api.commentsService.getByEntity(
      'ideas',
      props.ideaId,
      params,
    );

    if (nextPage === 1) {
      items.value = response.data;
    } else {
      items.value.push(...response.data);
    }

    // Update pagination state using helper
    const pagination = parsePaginationMeta(response.meta, pageSize, nextPage);
    if (response.meta) {
      hasMore.value = pagination.hasMore;
      page.value = pagination.currentPage;
    } else {
      hasMore.value = response.data.length >= pageSize;
      page.value = nextPage;
    }

    if (hasMore.value) {
      state.loaded();
    } else {
      state.complete();
    }
  } catch (e) {
    error.value = e instanceof Error ? e : new Error('Failed to load');
    state.error();
  }
};

const reset = () => {
  items.value = [];
  page.value = 0;
  hasMore.value = true;
  error.value = null;
};

// Handle new comment added
const handleNewComment = (comment: CommentResource) => {
  // Prepend new comment to the list
  items.value.unshift(comment);
  emit('comment-added');
};

// Handle comment deleted
const handleCommentDeleted = (commentId: number) => {
  items.value = items.value.filter((item) => item.id !== commentId);
};

// Handle comment updated. Also fires for pin/unpin (CommentItem reuses the `updated`
// emit), so reorder the local list to match the server's canonical ordering:
//   pinned_at DESC NULLS LAST, created_at DESC, id DESC (tie-break for stability)
const handleCommentUpdated = (updatedComment: CommentResource) => {
  const index = items.value.findIndex((item) => item.id === updatedComment.id);
  if (index === -1) return;
  items.value[index] = updatedComment;
  items.value.sort((a, b) => {
    const ap = a.pinned_at ? Date.parse(a.pinned_at) : null;
    const bp = b.pinned_at ? Date.parse(b.pinned_at) : null;
    if (ap !== null && bp !== null && ap !== bp) return bp - ap;
    if (ap !== null && bp === null) return -1;
    if (ap === null && bp !== null) return 1;
    const ac = a.created_at ? Date.parse(a.created_at) : 0;
    const bc = b.created_at ? Date.parse(b.created_at) : 0;
    if (ac !== bc) return bc - ac;
    return (b.id ?? 0) - (a.id ?? 0);
  });
};

// WebSocket: Listen for comment.finished events (image processing complete)
const { subscribe: subscribeLocation, unsubscribe: unsubscribeLocation } = useLocationChannel({
  onCommentFinished: async (commentId: number) => {
    const index = items.value.findIndex((item) => item.id === commentId);
    if (index !== -1) {
      try {
        const updated = await api.commentsService.get(commentId);
        items.value[index] = updated;
      } catch (e) {
        console.error('Failed to refresh comment after processing:', e);
      }
    }
  },
});

// Reset when modal closes, manage WebSocket subscription
watch(
  () => props.visible,
  (newVal) => {
    if (!newVal) {
      reset();
      // Don't unsubscribe — echo.leave() would destroy the shared channel
      // and kill List.vue's listeners. The callback is a no-op when items is empty.
    } else {
      subscribeLocation();
    }
  },
);

