  error.value = null;

  try {
    const params: QueryParams = {
      page: nextPage,
      per_page: pageSize,
      orders: [order('created_at', 'desc')],
    };

    const response: PaginatedResponse<ReactionResource> = await api.reactionsService.getByEntity(
      'ideas',
      props.ideaId,
      params
    );

    if (nextPage === 1) {
      items.value = response.data;
    } else {
      items.value.push(...response.data);
    }

    // Update pagination state using helper
    const pagination = parsePaginationMeta(response.meta, pageSize, nextPage);
    if (response.meta) {
      hasMore.value = pagination.hasMore;
      page.value = pagination.currentPage;
    } else {
      hasMore.value = response.data.length >= pageSize;
      page.value = nextPage;
    }

    if (hasMore.value) {
      state.loaded();
    } else {
      state.complete();
    }
  } catch (e) {
    error.value = e instanceof Error ? e : new Error('Failed to load');
    state.error();
  }
};

const reset = (reload = false) => {
  items.value = [];
  page.value = 0;
  hasMore.value = true;
  error.value = null;
  if (reload) {
    reloadKey.value++;
  }
};

// Calculate current reactions count from items
const getCurrentReactionsCount = (): ReactionCountItem[] => {
  const counts = new Map<string, number>();

  for (const item of items.value) {
    counts.set(item.reaction, (counts.get(item.reaction) ?? 0) + 1);
  }

  return Array.from(counts.entries()).map(([reaction, count]) => ({ reaction, count }));
};

// Handle reaction selection from picker
const handleReactionSelect = async (reactionType: ReactionType) => {
  if (!isAuthenticated.value || isReactionLoading.value) return;

  try {
    const currentCounts = getCurrentReactionsCount();
    const result = await toggle(
      props.ideaId,
      reactionType,
      props.userReaction,
      currentCounts
    );

    // Emit the change to parent
    emit('reaction-changed', {
      ideaId: props.ideaId,
      userReaction: result.userReaction,
      reactionsCount: result.reactionsCount,
    });

    // Reset and reload the list to show updated reactions
    reset(true);
  } catch (error) {
    if (isBlockedByContentOwner(error)) {
      toast.error(t('errors.blockedByContentOwner'));
    } else if (isAlreadyReacted(error)) {
      toast.error(t('errors.alreadyReacted'));
    } else {
      console.error('Failed to toggle reaction:', error);
    }
  }
};

// Reset when modal closes
watch(() => props.visible, (newVal) => {
  if (!newVal) {
    reset();
  }
});

